namespace sv_f8487a2dfabb4eda84c9d5db48918b83.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Eastside"),
        new("WH-003", "Warehouse C - Airport"),
        new("WH-004", "Warehouse D - Harbor")
    ];

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

public record Warehouse(string Id, string Name);

namespace sv_f8487a2dfabb4eda84c9d5db48918b83.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentLowStockCount { get; private set; }

    public event Func<Task>? OnAlertUpdated;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query — returns a random number between 0 and 15
        return Task.FromResult(_random.Next(0, 16));
    }

    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _cts = new CancellationTokenSource();
                _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
                _ = PollLoopAsync(_cts.Token);
            }
        }
    }

    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _cts?.Cancel();
                _cts?.Dispose();
                _cts = null;
                _timer?.Dispose();
                _timer = null;
            }
        }
    }

    public async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        if (OnAlertUpdated is not null)
            await OnAlertUpdated.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        // Do an immediate first poll
        await RefreshAsync();

        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(cancellationToken))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When warehouse changes, immediately refresh alerts
        if (_subscriberCount > 0)
            await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

