        _log.Add($"[{DateTime.Now:HH:mm:ss}] Dashboard opened for {WarehouseState.CurrentWarehouseName}");
    }

    private Task OnWarehouseChangedAsync()
    {
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Switched to {WarehouseState.CurrentWarehouseName}");
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    private Task OnAlertUpdatedAsync()
    {
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Alert update: {AlertService.CurrentLowStockCount} low-stock items at {WarehouseState.CurrentWarehouseName}");
