        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChangedAsync;
        AlertService.OnAlertUpdated -= OnAlertUpdatedAsync;

        // Stop polling when user leaves the page
        AlertService.StopPolling();
    }
}

